package de.bierverein.api;
import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import jakarta.annotation.PostConstruct; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AppUserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(AppUserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @PostConstruct void seedAdmin(){if(!users.existsByUsername("admin")){AppUser u=new AppUser();u.setUsername("admin");u.setPasswordHash(encoder.encode("admin123!"));u.setRole(Role.ADMIN);users.save(u);}}
 @PostMapping("/login") public LoginResponse login(@RequestBody LoginRequest req){AppUser u=users.findByUsername(req.username()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ungültige Zugangsdaten"));if(!u.isEnabled()||!encoder.matches(req.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ungültige Zugangsdaten");return new LoginResponse(jwt.create(u),u.getUsername(),u.getRole().name(),u.getMember()==null?null:u.getMember().getId(),u.getMember()==null?null:u.getMember().getName());}
 public record LoginRequest(String username,String password){} public record LoginResponse(String token,String username,String role,Long memberId,String memberName){}
}
